  <script>
    const products = [
      { name: "Linen throw blanket", category: "home", price: "$48", was: "$62", blurb: "Breathable texture, soft finish, and a versatile neutral tone.", accent: "Bestseller" },
      { name: "Ceramic bedside lamp", category: "home", price: "$74", was: "$92", blurb: "Soft diffusion and a compact profile for nightstands and desks.", accent: "New" },
      { name: "Aroma diffuser", category: "wellness", price: "$39", was: "$55", blurb: "Quiet misting with a minimal silhouette and gentle ambient light.", accent: "Member fave" },
      { name: "Wireless charging dock", category: "tech", price: "$59", was: "$79", blurb: "Charge your phone, buds, and watch from one tidy station.", accent: "Fast ship" },
      { name: "Bath essentials set", category: "wellness", price: "$52", was: "$68", blurb: "Three-step care with a clean scent profile and reusable storage.", accent: "Limited" },
      { name: "Smart table clock", category: "tech", price: "$88", was: "$108", blurb: "Alarm, ambient display, and temperature reading in one device.", accent: "Trending" },
      { name: "Accent tray", category: "home", price: "$28", was: "$34", blurb: "A small organizer that makes consoles, vanities, and coffee tables feel finished.", accent: "Editor pick" },
      { name: "Blue light reading lamp", category: "tech", price: "$66", was: "$84", blurb: "Warm lighting presets with a flexible neck and touch controls.", accent: "Top rated" },
    ];

    const productGrid = document.getElementById("product-grid");
    const filterButtons = Array.from(document.querySelectorAll("[data-filter]"));
    const toast = document.getElementById("toast");
    const newsletterForm = document.getElementById("newsletter-form");
    const emailInput = document.getElementById("email");

    const svgForCategory = (category) => {
      const palettes = {
        home: ["#0f766e", "#99f6e4"],
        wellness: ["#a16207", "#fde68a"],
        tech: ["#1d4ed8", "#bfdbfe"]
      };
      const [a, b] = palettes[category] || palettes.home;
      return `
          <svg viewBox="0 0 320 220" aria-hidden="true" focusable="false">
          <defs>
            <linearGradient id="g-${category}" x1="0%" x2="100%" y1="0%" y2="100%">
              <stop offset="0%" stop-color="${a}" />
              <stop offset="100%" stop-color="${b}" />
            </linearGradient>
          </defs>
          <rect x="35" y="28" width="250" height="150" rx="32" fill="url(#g-${category})" opacity="0.22" />
          <ellipse cx="165" cy="176" rx="92" ry="18" fill="#1e1b17" opacity="0.12" />
          <rect x="90" y="52" width="140" height="116" rx="24" fill="url(#g-${category})" />
          <circle cx="165" cy="106" r="26" fill="#ffffff" opacity="0.22" />
          <rect x="122" y="92" width="86" height="28" rx="14" fill="#ffffff" opacity="0.24" />
        </svg>
      `;
    };

    const renderProducts = (filter = "all") => {
      const items = filter === "all" ? products : products.filter((product) => product.category === filter);
      productGrid.innerHTML = items.map((product) => `
        <article class="card">
          <div class="product-visual">
            <span class="badge">${product.accent}</span>
            ${svgForCategory(product.category)}
          </div>
          <div class="card-body">
            <div class="meta-row">
              <h3>${product.name}</h3>
              <span class="price">${product.price}</span>
            </div>
            <p>${product.blurb}</p>
            <div class="meta-row">
              <span class="strike">${product.was}</span>
              <button class="btn btn-secondary" type="button">Add to bag</button>
            </div>
          </div>
        </article>
      `).join("");
    };

    const setActiveFilter = (value) => {
      filterButtons.forEach((button) => {
        const active = button.dataset.filter === value;
        button.classList.toggle("is-active", active);
        button.setAttribute("aria-pressed", String(active));
      });
    };

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => {
        const filter = button.dataset.filter;
        setActiveFilter(filter);
        renderProducts(filter);
      });
    });

    productGrid.addEventListener("click", (event) => {
      const button = event.target.closest("button");
      if (!button) return;

      toast.textContent = "Added to bag.";
      toast.classList.add("is-visible");
      window.clearTimeout(toast.hideTimer);
      toast.hideTimer = window.setTimeout(() => toast.classList.remove("is-visible"), 2000);
    });

    newsletterForm.addEventListener("submit", (event) => {
      event.preventDefault();
      const value = emailInput.value.trim();
      if (!value) {
        toast.textContent = "Please enter an email address.";
        toast.classList.add("is-visible");
        window.clearTimeout(toast.hideTimer);
        toast.hideTimer = window.setTimeout(() => toast.classList.remove("is-visible"), 2500);
        emailInput.focus();
        return;
      }

      newsletterForm.reset();
      toast.textContent = "Thanks — you're on the list.";
      toast.classList.add("is-visible");
      window.clearTimeout(toast.hideTimer);
      toast.hideTimer = window.setTimeout(() => toast.classList.remove("is-visible"), 2500);
    });

    renderProducts();
  </script>
